def crc16_ccitt_byte(crc: int, byte: int) -> int:
    mask16 = 65535
    poly = 4129
    curr = (crc ^ (byte & 255) << 8) & mask16
    for _ in range(8):
        if curr & 32768 != 0:
            curr = (curr << 1 ^ poly) & mask16
        else:
            curr = curr << 1 & mask16
    return curr

def crc32c_castagnoli_step(crc: int, byte: int) -> int:
    mask32 = (1 << 32) - 1
    poly = 33526 << 16 | 15224
    curr = (crc ^ byte & 255) & mask32
    for _ in range(8):
        if curr & 1 != 0:
            curr = (curr >> 1 ^ poly) & mask32
        else:
            curr = curr >> 1 & mask32
    return curr

def adler32_checksum_chunk(a: int, b: int, data: list[int]) -> tuple[int, int]:
    mod_base = 65521
    acc_a = a % mod_base
    acc_b = b % mod_base
    for val in data:
        byte = val & 255
        acc_a = (acc_a + byte) % mod_base
        acc_b = (acc_b + acc_a) % mod_base
    return (acc_a, acc_b)

def cobs_decode_frame(encoded: list[int]) -> list[int]:
    n = len(encoded)
    if n == 0:
        return []
    out = []
    idx = 0
    while idx < n:
        code = encoded[idx] & 255
        if code == 0:
            break
        idx = idx + 1
        num_copy = code - 1
        for _ in range(num_copy):
            if idx < n:
                out.append(encoded[idx] & 255)
                idx = idx + 1
        if code < 255 and idx < n:
            out.append(0)
    return out

def slip_unescape_frame(framed: list[int]) -> list[int]:
    n = len(framed)
    if n == 0:
        return []
    end_byte = 192
    esc_byte = 219
    esc_end = 220
    esc_esc = 221
    out = []
    idx = 0
    while idx < n:
        b = framed[idx] & 255
        if b == end_byte:
            idx = idx + 1
        elif b == esc_byte:
            idx = idx + 1
            if idx < n:
                sub = framed[idx] & 255
                if sub == esc_end:
                    out.append(end_byte)
                elif sub == esc_esc:
                    out.append(esc_byte)
                else:
                    out.append(sub)
                idx = idx + 1
        else:
            out.append(b)
            idx = idx + 1
    return out

def hdlc_bit_stuffing(bits: list[int]) -> list[int]:
    out = []
    ones_count = 0
    for b in bits:
        bit_val = 1 if b != 0 else 0
        out.append(bit_val)
        if bit_val == 1:
            ones_count = ones_count + 1
            if ones_count == 5:
                out.append(0)
                ones_count = 0
        else:
            ones_count = 0
    return out

def shamir_secret_eval_poly(coeffs: list[int], x: int, prime: int) -> int:
    if prime <= 1:
        return 0
    acc = 0
    x_mod = x % prime
    for c in reversed(coeffs):
        term = (acc * x_mod + c) % prime
        acc = term
    return acc

def sponge_permutation_keccak_round(state: list[int], round_const: int) -> list[int]:
    mask = (1 << 32) - 1
    st = list(state)
    while len(st) < 25:
        st.append(0)
    st = [s & mask for s in st[:25]]
    c = [0] * 5
    for i in range(25):
        c[i % 5] = c[i % 5] ^ st[i]
    d = [0] * 5
    for x in range(5):
        r = c[(x + 1) % 5]
        rot = (r << 1 | r >> 31) & mask
        d[x] = c[(x + 4) % 5] ^ rot
    for i in range(25):
        st[i] = st[i] ^ d[i % 5]
    b = list(st)
    for x in range(5):
        for y in range(5):
            idx = x + 5 * y
            shift = (x + 2 * y) * (x + 2 * y + 1) // 2 % 32
            v = st[idx]
            b[y + 5 * ((2 * x + 3 * y) % 5)] = (v << shift | v >> 32 - shift) & mask if shift != 0 else v
    out = [0] * 25
    for y in range(5):
        for x in range(5):
            idx = x + 5 * y
            out[idx] = b[idx] ^ ~b[(x + 1) % 5 + 5 * y] & b[(x + 2) % 5 + 5 * y] & mask
    out[0] = out[0] ^ round_const & mask
    return out

def varint_protobuf_encode(val: int) -> list[int]:
    v = val if val >= 0 else 0
    out = []
    while True:
        byte = v & 127
        v = v >> 7
        if v != 0:
            out.append(byte | 128)
        else:
            out.append(byte)
            break
    return out

def varint_protobuf_decode(bytes_list: list[int]) -> tuple[int, int]:
    res = 0
    shift = 0
    consumed = 0
    for b in bytes_list:
        byte_val = b & 255
        res = res | (byte_val & 127) << shift
        consumed = consumed + 1
        shift = shift + 7
        if byte_val & 128 == 0 or shift >= 70:
            break
    return (res, consumed)

def bech32_polymod_checksum(values: list[int]) -> int:
    gen = [992819391, 789488153, 1040649840, 956499247, 1034456622]
    c = 1
    for v in values:
        c0 = c >> 25
        c = (c & 33554431) << 5 ^ v & 31
        for i in range(5):
            if c0 >> i & 1 != 0:
                c = c ^ gen[i]
    return c
